#!/usr/bin/env python3
from pathlib import Path
import re

ROOT = Path(__file__).resolve().parents[1]

def read(path): return (ROOT/path).read_text(encoding='utf-8')
def write(path,text):
    p=ROOT/path; p.parent.mkdir(parents=True,exist_ok=True); p.write_text(text,encoding='utf-8')
def replace_once(path,old,new):
    text=read(path); count=text.count(old)
    if count != 1: raise SystemExit(f'{path}: expected one match, got {count}: {old[:100]!r}')
    write(path,text.replace(old,new,1))

def assert_has(path,*needles):
    text=read(path)
    for needle in needles:
        if needle not in text: raise SystemExit(f'{path}: missing expected marker {needle!r}')

def assert_not(path,*needles):
    text=read(path)
    for needle in needles:
        if needle in text: raise SystemExit(f'{path}: forbidden marker remains {needle!r}')

